def diagonal_order_values(grid):
    """The nonzero cells read in anti-diagonal order (by r+c, ties left to right)."""
    n = len(grid)
    return [v for _, _, v in sorted(((r, c, grid[r][c]) for r in range(n) for c in range(n) if grid[r][c] != 0),
                                    key=lambda t: (t[0] + t[1], t[1]))]

def pack_square(values):
    """The values as a k x k row-major grid, k = ceil(sqrt(len))."""
    k = int(len(values) ** 0.5)
    return [values[i * k:(i + 1) * k] for i in range(k)]
